const TIMEOUT_MS = 15 * 60 * 1000;
const sessions = new Map();

function startSession(username) {
  const id = Math.random().toString(36).slice(2);
  sessions.set(id, { username, expires: Date.now() + TIMEOUT_MS });
  return id;
}

